solution:
interface DiscountStrategy {
    long apply(long amount);
}

class NoDiscount implements DiscountStrategy {
    public long apply(long amount) { return amount; }
}

class PercentageDiscount implements DiscountStrategy {
    private final int percent;
    PercentageDiscount(int percent) { this.percent = percent; }
    public long apply(long amount) { return amount - (amount * percent / 100); }
}

class Checkout {
    private final DiscountStrategy discount;
    Checkout(DiscountStrategy discount) { this.discount = discount; }
    long total(long amount) { return discount.apply(amount); }
}
